cypress_script:
describe('Customer Registration Form', () => {
  it('should register a new user successfully', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[id="customer.firstName"]').type('John');
    cy.get('input[id="customer.lastName"]').type('Doe');
    cy.get('input[id="customer.address.street"]').type('123 Main St');
    cy.get('input[id="customer.address.city"]').type('Anytown');
    cy.get('input[id="customer.address.state"]').type('CA');
    cy.get('input[id="customer.address.zipCode"]').type('12345');
    cy.get('input[id="customer.phoneNumber"]').type('555-1234');
    cy.get('input[id="customer.ssn"]').type('123-45-6789');
    cy.get('input[id="customer.username"]').type('johndoe');
    cy.get('input[id="customer.password"]').type('password123');
    cy.get('input[id="repeatedPassword"]').type('password123');
    cy.get('input[type="submit"][value="Register"]').click();
    cy.url().should('not.eq', 'https://parabank.parasoft.com/parabank/register.htm');
  });
  it('should not register if required fields are empty', () => {
    cy.visit('https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[type="submit"][value="Register"]').click();
    cy.url().should('eq', 'https://parabank.parasoft.com/parabank/register.htm');
    cy.get('input[id="customer.firstName"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Customer Registration Form', () => {
   test('should register a new user successfully', async ({ page }) => {
     await page.goto('https://parabank.parasoft.com/parabank/register.htm');
     await page.fill('input[id="customer.firstName"]', 'John');
     await page.fill('input[id="customer.lastName"]', 'Doe');
     await page.fill('input[id="customer.address.street"]', '123 Main St');
     await page.fill('input[id="customer.address.city"]', 'Anytown');
     await page.fill('input[id="customer.address.state"]', 'CA');
     await page.fill('input[id="customer.address.zipCode"]', '12345');
     await page.fill('input[id="customer.phoneNumber"]', '555-1234');
     await page.fill('input[id="customer.ssn"]', '123-45-6789');
     await page.fill('input[id="customer.username"]', 'johndoe');
     await page.fill('input[id="customer.password"]', 'password123');
     await page.fill('input[id="repeatedPassword"]', 'password123');
     await page.click('input[type="submit"][value="Register"]');
     await expect(page.url()).not.toBe('https://parabank.parasoft.com/parabank/register.htm');
   });
   test('should not register if required fields are empty', async ({ page }) => {
     await page.goto('https://parabank.parasoft.com/parabank/register.htm');
     await page.click('input[type="submit"][value="Register"]');
     await expect(page.url()).toBe('https://parabank.parasoft.com/parabank/register.htm');
     await expect(page.locator('input[id="customer.firstName"]').isVisible()).toBeTruthy();
   });
});
